def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform separator rows and columns define rectangular tiles.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def spans(n, cuts):
        out=[]; start=0
        for cut in cuts:
            if start < cut: out.append((start, cut))
            start = cut + 1
        if start < n: out.append((start, n))
        return out
    rs, cs = spans(h, sep_rows), spans(w, sep_cols)
    dividers = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    from collections import Counter
    counts = Counter(v for row in grid for v in row if v not in dividers)
    marker = min(counts, key=lambda v: (counts[v], v))
    background = max(counts, key=lambda v: (counts[v], -v))
    return [[1 if sum(grid[r][c] == marker for r in range(a,b) for c in range(x,y)) == 2 else background
             for x,y in cs] for a,b in rs]
